original_raw_output:
// Vulnerable code: SQL injection due to improper use of Statement
String userId = request.getParameter("userId"); // User-controlled input
Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/db");
Statement stmt = conn.createStatement();
// Vulnerable: concatenates user input directly into query
ResultSet rs = stmt.executeQuery("SELECT * FROM users WHERE id = " + userId);

***

// Fixed code: uses PreparedStatement to sanitize input
String userId = request.getParameter("userId"); // User-controlled input
Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/db");
// Safe: parameterized query prevents SQL injection
PreparedStatement pstmt = conn.prepareStatement("SELECT * FROM users WHERE id = ?");
pstmt.setString(1, userId); // Input is properly sanitized by API
ResultSet rs = pstmt.executeQuery();

